{
  "name": "opencode-macos-notify",
  "version": "0.1.2",
  "description": "Native macOS notifications for opencode: generation finished, errors, and permission requests with Allow / Always Allow / Deny buttons.",
  "license": "MIT",
  "type": "module",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "files": [
    "src",
    "swift",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "macos",
    "notifications",
    "permissions"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/makstamoian/opencode-macos-notify.git"
  },
  "bugs": {
    "url": "https://github.com/makstamoian/opencode-macos-notify/issues"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^24.0.0",
    "typescript": "^5.7.0"
  }
}
